"use client";

import { useState, useEffect } from 'react';
import Image from 'next/image';
import { FiUpload, FiEdit2, FiTrash2, FiRefreshCw } from 'react-icons/fi';

interface Photo {
  id: string;
  title: string;
  description: string;
  url: string;
  category: string;
  featured: boolean;
}

export default function PhotosPage() {
  const [photos, setPhotos] = useState<Photo[]>([
    {
      id: '1',
      title: 'Mountain Sunset',
      description: 'Beautiful sunset over the mountains',
      url: '/images/mountain-sunset.jpg',
      category: 'Landscape',
      featured: true
    },
    {
      id: '2',
      title: 'Ocean Waves',
      description: 'Waves crashing on the shore',
      url: '/images/ocean-waves.jpg',
      category: 'Seascape',
      featured: false
    }
  ]);

  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [editingPhoto, setEditingPhoto] = useState<Photo | null>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      // Simulate file upload
      await new Promise(resolve => setTimeout(resolve, 1000));
      const newPhoto: Photo = {
        id: Date.now().toString(),
        title: file.name.replace(/\.[^/.]+$/, ''),
        description: '',
        url: URL.createObjectURL(file),
        category: 'Uncategorized',
        featured: false
      };
      setPhotos([...photos, newPhoto]);
    } catch (error) {
      console.error('Error uploading photo:', error);
    } finally {
      setIsUploading(false);
    }
  };

  const handleDeletePhoto = (photoId: string) => {
    if (window.confirm('Are you sure you want to delete this photo?')) {
      setPhotos(photos.filter(photo => photo.id !== photoId));
    }
  };

  const handleToggleFeatured = (photoId: string) => {
    setPhotos(photos.map(photo =>
      photo.id === photoId
        ? { ...photo, featured: !photo.featured }
        : photo
    ));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-white">Photos</h1>
        <div className="flex items-center space-x-4">
          <label className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 cursor-pointer">
            <FiUpload className="-ml-1 mr-2 h-4 w-4" />
            Upload Photo
            <input
              type="file"
              accept="image/*"
              onChange={handleFileUpload}
              className="hidden"
              disabled={isUploading}
            />
          </label>
        </div>
      </div>

      {isLoading ? (
        <div className="flex items-center justify-center h-64">
          <FiRefreshCw className="animate-spin h-8 w-8 text-white" />
        </div>
      ) : photos.length === 0 ? (
        <div className="text-center py-12">
          <FiUpload className="mx-auto h-12 w-12 text-zinc-400" />
          <h3 className="mt-2 text-sm font-medium text-white">No photos</h3>
          <p className="mt-1 text-sm text-zinc-400">Get started by uploading a new photo.</p>
          <div className="mt-6">
            <label className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 cursor-pointer">
              <FiUpload className="-ml-1 mr-2 h-4 w-4" />
              Upload Photo
              <input
                type="file"
                accept="image/*"
                onChange={handleFileUpload}
                className="hidden"
                disabled={isUploading}
              />
            </label>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {photos.map((photo) => (
            <div key={photo.id} className="bg-zinc-800 rounded-lg overflow-hidden">
              <div className="relative h-48">
                <Image
                  src={photo.url}
                  alt={photo.title}
                  fill
                  className="object-cover"
                />
                <div className="absolute inset-0 bg-black bg-opacity-0 hover:bg-opacity-40 transition-opacity duration-200">
                  <div className="absolute top-2 right-2 flex space-x-2">
                    <button
                      onClick={() => setEditingPhoto(photo)}
                      className="p-2 text-white hover:text-blue-400 transition-colors"
                    >
                      <FiEdit2 className="h-5 w-5" />
                    </button>
                    <button
                      onClick={() => handleDeletePhoto(photo.id)}
                      className="p-2 text-white hover:text-red-400 transition-colors"
                    >
                      <FiTrash2 className="h-5 w-5" />
                    </button>
                  </div>
                </div>
              </div>
              <div className="p-4">
                <h3 className="text-lg font-medium text-white">{photo.title}</h3>
                <p className="mt-1 text-sm text-zinc-400">{photo.description}</p>
                <div className="mt-4 flex items-center justify-between">
                  <span className="text-sm text-zinc-400">{photo.category}</span>
                  <button
                    onClick={() => handleToggleFeatured(photo.id)}
                    className={`px-2 py-1 text-xs font-medium rounded-full ${
                      photo.featured
                        ? 'bg-yellow-100 text-yellow-800'
                        : 'bg-zinc-700 text-zinc-300'
                    }`}
                  >
                    {photo.featured ? 'Featured' : 'Not Featured'}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Edit Photo Modal */}
      {editingPhoto && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center">
          <div className="bg-zinc-800 rounded-lg p-6 w-full max-w-md">
            <h2 className="text-xl font-bold text-white mb-4">Edit Photo</h2>
            <form className="space-y-4">
              <div>
                <label htmlFor="title" className="block text-sm font-medium text-zinc-400">
                  Title
                </label>
                <input
                  type="text"
                  id="title"
                  defaultValue={editingPhoto.title}
                  className="mt-1 block w-full rounded-md bg-zinc-700 border-zinc-600 text-white shadow-sm focus:border-blue-500 focus:ring-blue-500"
                />
              </div>
              <div>
                <label htmlFor="description" className="block text-sm font-medium text-zinc-400">
                  Description
                </label>
                <textarea
                  id="description"
                  defaultValue={editingPhoto.description}
                  rows={3}
                  className="mt-1 block w-full rounded-md bg-zinc-700 border-zinc-600 text-white shadow-sm focus:border-blue-500 focus:ring-blue-500"
                />
              </div>
              <div>
                <label htmlFor="category" className="block text-sm font-medium text-zinc-400">
                  Category
                </label>
                <input
                  type="text"
                  id="category"
                  defaultValue={editingPhoto.category}
                  className="mt-1 block w-full rounded-md bg-zinc-700 border-zinc-600 text-white shadow-sm focus:border-blue-500 focus:ring-blue-500"
                />
              </div>
              <div className="flex items-center">
                <input
                  type="checkbox"
                  id="featured"
                  defaultChecked={editingPhoto.featured}
                  className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-zinc-600 rounded bg-zinc-700"
                />
                <label htmlFor="featured" className="ml-2 block text-sm text-zinc-400">
                  Featured Photo
                </label>
              </div>
              <div className="flex justify-end space-x-3 mt-6">
                <button
                  type="button"
                  onClick={() => setEditingPhoto(null)}
                  className="px-4 py-2 border border-zinc-600 rounded-md text-sm font-medium text-zinc-300 hover:bg-zinc-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                >
                  Save Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
} 